Do not provide any other text or markdown fences.

Here is the original Java 11 code you have to translate:
<original_code>
import java.io.BufferedWriter;
import java.io.DataInputStream;
import java.io.IOException;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.HashMap;
import java.util.Map;

public class Test {
    static PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
    int R, C;
    long[][] ch;
    int[] cntA = new int[61], cntB = new int[61];
    long best = Long.MAX_VALUE;
    String str;
    Map<Integer, Map<Integer, Map<Long, Long>>> cache = new HashMap<>();

    static class FastReader {
        final private int BUFFER_SIZE = 1 << 16;
        private DataInputStream din;
        private byte[] buffer;
        private int bufferPointer, bytesRead;
        public FastReader() {
            din = new DataInputStream(System.in);
            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }
        private byte read() throws IOException {
            if (bufferPointer == bytesRead) {
                bytesRead = din.read(buffer, 0, BUFFER_SIZE);
                if (bytesRead == -1) return -1;
                bufferPointer = 0;
            }
            return buffer[bufferPointer++];
        }
        public int nextInt() throws IOException {
            int ret = 0;
            byte c = read();
            while (c <= ' ') c = read();
            boolean neg = (c == '-');
            if (neg) c = read();
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');
            return neg ? -ret : ret;
        }
        public long nextLong() throws IOException {
            long ret = 0;
            byte c = read();
            while (c <= ' ') c = read();
            boolean neg = (c == '-');
            if (neg) c = read();
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');
            return neg ? -ret : ret;
        }
        public String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            byte c = read();
            while (c <= ' ') c = read();
            do {
                sb.append((char) c);
            } while ((c = read()) > ' ');
            return sb.toString();
        }
    }

    FastReader fr = new FastReader();

    int readInt() { try { return fr.nextInt(); } catch (IOException e) { return 0; } }
    long readLong() { try { return fr.nextLong(); } catch (IOException e) { return 0; } }
    String readString() { try { return fr.next(); } catch (IOException e) { return ""; } }

    Long cacheGet(int v1, int v2, long x) {
        Map<Integer, Map<Long, Long>> m1 = cache.get(v1);
        if (m1 == null) return null;
        Map<Long, Long> m2 = m1.get(v2);
        if (m2 == null) return null;
        return m2.get(x);
    }
    void cachePut(int v1, int v2, long x, long val) {
        cache.computeIfAbsent(v1, k -> new HashMap<>())
             .computeIfAbsent(v2, k -> new HashMap<>())
             .put(x, val);
    }

    public static void main(String[] args) {
        Test te = new Test();
        te.start();
        writer.flush();
    }

    void computeBinomial(int maxN) {
        ch = new long[maxN + 1][];
        long[] prev = null;
        for (int i = 0; i <= maxN; i++) {
            long[] cur = new long[i + 1];
            cur[0] = cur[i] = 1;
            for (int j = 1; j < i; j++) {
                cur[j] = prev[j - 1] + prev[j];
            }
            ch[i] = cur;
            prev = cur;
        }
    }

    void dfs(long x, long y, int v1, int v2) {
        long diff = Math.abs(x - y);
        if (best <= 1 || diff - ch[v1][R] * ch[v2][R] >= best) return;
        if (v1 == R - 1 && v2 == R - 1) {
            if (diff < best) best = diff;
            return;
        }
        if (v1 >= R) {
            long cur = ch[v1][R] - ch[v1 - 1][R];
            long other = ch[v2][R];
            dfs(x, y + cur * other, v1 - 1, v2);
        }
        if (v2 >= R) {
            long cur = ch[v2][R] - ch[v2 - 1][R];
            long other = ch[v1][R];
            dfs(x + cur * other, y, v1, v2 - 1);
        }
    }

    long solve(long x, long y, int v1, int v2) {
        long diff = Math.abs(x - y);
        if (diff - ch[v1][R] * ch[v2][R] > best) return 0;
        Long v = cacheGet(v1, v2, x);
        if (v != null) return v;
        if (v1 < R || v2 < R) {
            if (v1 >= cntA[v1 + v2] && v2 >= cntB[v1 + v2]) {
                int sum = v1 + v2;
                v1 -= cntA[sum];
                v2 -= cntB[sum];
                return ch[v1 + v2][v1];
            }
            return 0;
        }
        long ans = 0;
        char c = str.charAt(v1 + v2 - 1);
        if (c != 'A') {
            long cur = ch[v2][R] - ch[v2 - 1][R];
            long other = ch[v1][R];
            ans += solve(x + cur * other, y, v1, v2 - 1);
        }
        if (c != 'B') {
            long cur = ch[v1][R] - ch[v1 - 1][R];
            long other = ch[v2][R];
            ans += solve(x, y + cur * other, v1 - 1, v2);
        }
        cachePut(v1, v2, x, ans);
        return ans;
    }

    void start() {
        R = readInt();
        C = readInt();
        int maxN = 2 * (R + C);
        computeBinomial(maxN);
        long x = 0, y = 0;
        int v1 = R + C, v2 = R + C;
        while (v1 >= R && v2 >= R)
            if (x > y) {
                long cur = ch[v1][R] - ch[v1 - 1][R];
                long other = ch[v2][R];
                y += cur * other;
                v1--;
            } else {
                long cur = ch[v2][R] - ch[v2 - 1][R];
                long other = ch[v1][R];
                x += cur * other;
                v2--;
            }
        best = Math.abs(x - y);
        dfs(0, 0, R + C, R + C);
        str = readString();
        for (int i = 0; i < 2 * (R + C); i++) {
            cntA[i + 1] = cntA[i] + (str.charAt(i) == 'A' ? 1 : 0);
            cntB[i + 1] = cntB[i] + (str.charAt(i) == 'B' ? 1 : 0);
        }
        long ans = solve(0, 0, R + C, R + C);
        writer.println(ans);
    }
}
